from heapq import heappop, heappush
from itertools import count

class ReviewQueue:
    def __init__(self):
        self.heap = []
        self.active = {}
        self.order = count()

    def schedule(self, task, priority):
        if task in self.active:
            self.active[task][-1] = None  # Void the old entry.
        entry = [priority, next(self.order), task]
        self.active[task] = entry
        heappush(self.heap, entry)

    def cancel(self, task):
        self.active.pop(task)[-1] = None

    def next_task(self):
        while self.heap:
            priority, _, task = heappop(self.heap)
            if task is not None:
                del self.active[task]
                return task, priority
        raise KeyError('no scheduled tasks')

queue = ReviewQueue()
queue.schedule('loops', 5)
queue.schedule('files', 2)
queue.schedule('loops', 1)
